function polygonFeature(
  agencySlug: string,
  sourceUrl: string,
  sourceLabel: string,
  coordinates: [number, number][],
): GeoJSON.Feature<GeoJSON.Polygon> {
  return {
    type: 'Feature',
    properties: { agencySlug, serviceType: 'on-demand', sourceUrl, sourceLabel },
    geometry: { type: 'Polygon', coordinates: [coordinates] },
  };
}

